<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {request,ApiError} from '../lib/api';
import {MARD_PALETTE,paletteColors,paletteLabel,colorCode,beadHeight,beadAxisTicks,beadCounts,convertLegacyPixels,beadProgress,beadLine,beadFill,resizePattern,quantizeBeads,paintBeads,exportBeads,validBeadData,type BeadWork} from '../lib/beads';
import {beadPatterns} from '../lib/bead-patterns';
import BeadThumbnail from './BeadThumbnail.vue';
const props=defineProps<{accountId:string;foreground:boolean}>();const emit=defineEmits<{(e:'auth-expired'):void}>();
const project=ref<BeadWork|null>(null),canvas=ref<HTMLCanvasElement|null>(null),viewport=ref<HTMLElement|null>(null),fileInput=ref<HTMLInputElement|null>(null),cropCanvas=ref<HTMLCanvasElement|null>(null);
const ruler=ref<HTMLCanvasElement|null>(null),hoveredCell=ref<number|null>(null);
const selected=ref(1),tool=ref('pen'),zoom=ref(1),guide=ref(true),sound=ref(false),dirty=ref(false),saving=ref(false),conflict=ref(false),saveState=ref(''),error=ref(''),notice=ref(''),melting=ref(false);
