const storageKey='mind-offline-beads-draft:'+props.accountId;
const progress=computed(()=>project.value?beadProgress(project.value.data):{filled:0,total:0,correct:0,extra:0,complete:false});
const colors=computed(()=>paletteColors(project.value?project.value.data.palette:MARD_PALETTE));
const beadPalette=computed(()=>colors.value.map(c=>c.hex));
const colorSearch=ref(''),colorSeries=ref('all'),colorTone=ref('all'),onlyUsed=ref(false);
const counts=computed(()=>project.value?beadCounts(project.value.data):colors.value.map((_,color)=>({color,placed:0,left:0})));
const visibleColors=computed(()=>colors.value.map((c,index)=>({...c,index})).filter(c=>c.index>0&&(!onlyUsed.value||counts.value[c.index].placed>0||counts.value[c.index].left>0)&&(colorSeries.value==='all'||c.series===colorSeries.value)&&(colorTone.value==='all'||c.tone===colorTone.value)&&(!colorSearch.value.trim()||(c.code+' '+c.hex+' '+c.tone).toUpperCase().includes(colorSearch.value.trim().toUpperCase().replace(/^MARD\s*/,'')))));
const series=computed(()=>[...new Set(colors.value.slice(1).map(c=>c.series))]);
const dockColors=computed(()=>{const used=colors.value.map((c,index)=>({...c,index})).filter(c=>c.index>0&&(counts.value[c.index].placed||counts.value[c.index].left));const source=used.length?used:colors.value.map((c,index)=>({...c,index})).slice(1);return source.slice(0,28);});
const boardSide=computed(()=>(project.value?.data.size||16)*20*zoom.value);
