const validDimensions=computed(()=>[createSize.value,createHeight.value].every(n=>Number.isInteger(n)&&n>=8&&n<=128));
const viewBox=ref({left:0,top:0,width:100,height:100});let locationIndex=-1;const locatedCell=ref<number|null>(null);let conversionTimer:ReturnType<typeof setTimeout>|undefined;
function drawRulers(){const v=viewport.value,c=canvas.value,r=ruler.value,d=project.value?.data;if(!v||!c||!r||!d||!v.clientWidth)return;const vr=v.getBoundingClientRect(),cr=c.getBoundingClientRect(),ratio=Math.min(window.devicePixelRatio||1,2);if(r.width!==Math.round(vr.width*ratio)||r.height!==Math.round(vr.height*ratio)){r.width=Math.round(vr.width*ratio);r.height=Math.round(vr.height*ratio);}const ctx=r.getContext('2d')!;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,vr.width,vr.height);ctx.fillStyle='#eeefe2';ctx.fillRect(0,0,vr.width,25);ctx.fillRect(0,0,31,vr.height);ctx.strokeStyle='#dce1cf';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(31,0);ctx.lineTo(31,vr.height);ctx.moveTo(0,25);ctx.lineTo(vr.width,25);ctx.stroke();const cw=cr.width/d.size,ch=cr.height/beadHeight(d),x0=cr.left-vr.left,y0=cr.top-vr.top;ctx.font='10px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#929e7e';ctx.save();ctx.beginPath();ctx.rect(32,0,vr.width-32,25);ctx.clip();for(const n of beadAxisTicks(d.size,cw)){const x=x0+(n-.5)*cw;if(x>=31&&x<=vr.width)ctx.fillText(String(n),x,12);}ctx.restore();ctx.save();ctx.beginPath();ctx.rect(0,26,31,vr.height-26);ctx.clip();for(const n of beadAxisTicks(beadHeight(d),ch)){const y=y0+(n-.5)*ch;if(y>=25&&y<=vr.height)ctx.fillText(String(n),15,y);}ctx.restore();ctx.fillStyle='#a5ae96';ctx.font='9px sans-serif';ctx.fillText('行/列',15,12);}
function syncViewport(){const v=viewport.value,c=canvas.value;if(!v||!c||!v.clientWidth)return;const vr=v.getBoundingClientRect(),cr=c.getBoundingClientRect(),style=getComputedStyle(v),left=vr.left+v.clientLeft+parseFloat(style.paddingLeft),top=vr.top+v.clientTop+parseFloat(style.paddingTop),right=vr.left+v.clientLeft+v.clientWidth-parseFloat(style.paddingRight),bottom=vr.top+v.clientTop+v.clientHeight-parseFloat(style.paddingBottom);viewBox.value={left:Math.max(0,Math.min(100,(left-cr.left)/cr.width*100)),top:Math.max(0,Math.min(100,(top-cr.top)/cr.height*100)),width:Math.max(0,Math.min(cr.right,right)-Math.max(cr.left,left))/cr.width*100,height:Math.max(0,Math.min(cr.bottom,bottom)-Math.max(cr.top,top))/cr.height*100};drawRulers();}
function jumpMap(e:PointerEvent){const v=viewport.value;if(!v)return;const r=(e.currentTarget as HTMLElement).getBoundingClientRect();v.scrollLeft=(e.clientX-r.left)/r.width*boardSide.value-v.clientWidth/2;v.scrollTop=(e.clientY-r.top)/r.height*boardHeightSide.value-v.clientHeight/2;syncViewport();}
function locateColor(){const d=project.value?.data,v=viewport.value;if(!d||!v)return;const source=d.mode==='guided'?d.target:d.pixels;const positions=source.map((c,i)=>c===selected.value?i:-1).filter(i=>i>=0);if(!positions.length){notice.value='这张图暂时没有 '+colorCode(selected.value,d.palette)+'。';return;}locationIndex=(locationIndex+1)%positions.length;const i=positions[locationIndex];v.scrollLeft=(i%d.size+.5)*20*zoom.value-v.clientWidth/2;v.scrollTop=(Math.floor(i/d.size)+.5)*20*zoom.value-v.clientHeight/2;syncViewport();locatedCell.value=i;hoveredCell.value=i;invalidate();notice.value=colorCode(selected.value,d.palette)+' · 第'+(Math.floor(i/d.size)+1)+'行，第'+(i%d.size+1)+'列 · '+(locationIndex+1)+' / '+positions.length+'处';}
function imageAspect(extent:number){if(!image)return;extent=Math.max(8,Math.min(128,Math.round(extent)||64));const ratio=image.naturalWidth/image.naturalHeight;createSize.value=ratio>=1?extent:Math.max(8,Math.round(extent*ratio));createHeight.value=ratio>=1?Math.max(8,Math.round(extent/ratio)):extent;}
function setDimensions(n:number){if(dialog.value==='image'&&image)imageAspect(n);else{createSize.value=n;createHeight.value=n;}}
async function convertOld(){if(!project.value||saving.value||!await beforeSwitch())return;const copy=JSON.parse(JSON.stringify(project.value)) as BeadWork;copy.id=crypto.randomUUID();copy.revision=0;copy.data.palette=MARD_PALETTE;copy.data.pixels=convertLegacyPixels(copy.data.pixels);copy.data.target=convertLegacyPixels(copy.data.target);copy.data.name=copy.data.name.slice(0,30)+' · MARD';project.value=copy;resetHistory();changed();await fit();await save();}
const percent=computed(()=>progress.value.total?Math.round(progress.value.correct/progress.value.total*100):0);
function fail(e:unknown){if(disposed)return;if(e instanceof ApiError&&e.status===401)emit('auth-expired');if(!(e instanceof ApiError&&e.status===0))error.value=(e as Error).message;}
function draft(){if(!project.value)return;try{localStorage.setItem(storageKey,JSON.stringify({work:{...project.value,data:{...project.value.data,name:project.value.data.name.trim()||'未命名拼豆'}},dirty:dirty.value}));}catch{notice.value='本机草稿空间不足，请及时保存到作品库。';}}
